// ---------- pyramid ----------
function pyramid(d,agen,src){const {nf}=A(); const codes=[...new Set(Object.keys(d.F||{}).concat(Object.keys(d.M||{})))].map(Number).sort((a,b)=>b-a);
  const mx=Math.max(1,...codes.flatMap(c=>[((d.F||{})[c]||[0])[0]||0,((d.M||{})[c]||[0])[0]||0]));
  const keys=codes.flatMap(c=>[["F",c],["M",c]]); const H5=compl(keys.map(([s,c])=>((d[s]||{})[c]||[null])[0])); const hid=(s,c)=>H5.has(keys.findIndex(k=>k[0]===s&&k[1]===c));
  const cell=(s,c,side)=>{let v=((d[s]||{})[c]||[null])[0]; const h=hid(s,c); const lab=v==null?"–":h?(n5(v)?"&lt;5":"ukr."):nf(v); if(h) v=null; const w=v?Math.max(1,100*v/mx):0; return `<div class="${side}" title="${s==="F"?"Kobiety":"Mężczyźni"}, ${agen[c]||c}: ${h?"ukryte (<5 lub komplementarnie)":v==null?"brak danych":nf(v)} · ${src}">${side==="l"?`<span class="num">${lab}</span><div class="b" style="width:${w}%"></div>`:`<div class="b" style="width:${w}%"></div><span class="num">${lab}</span>`}</div>`;};
  return `<div class="pyr"><div class="c" style="grid-column:1;text-align:right;color:var(--sysPink);font-weight:600">Kobiety</div><div></div><div class="c" style="text-align:left;color:var(--sysBlue);font-weight:600">Mężczyźni</div>${codes.map(c=>cell("F",c,"l")+`<div class="c">${A().esc(agen[c]||c)}</div>`+cell("M",c,"r")).join("")}</div>`;}
